	call FE_LanguageSelect_Draw
	ld a, BANK(FE_FadeInScreenSlow)
	ld hl, FE_FadeInScreenSlow
	call FarCall_A_HL
	ld a, $01
	ldh [rSVBK], a
	call FE_LanguageSelect_Input
	ret


FE_LanguageSelect_Input::
	ld a, BANK(FE_ReadJoypadHeld)
	ld hl, FE_ReadJoypadHeld
	call FarCall_A_HL
	ldh a, [hFE_JoyInput]
	bit 4, a
	jr z, .skip_7d15
	ld a, BANK(FE_TurnChoiceRight)
	ld hl, FE_TurnChoiceRight
	call FarCall_A_HL
.skip_7d15:
	ldh a, [hFE_JoyInput]
	bit 5, a
	jr z, .skip_7d23
	ld a, BANK(FE_TurnChoiceLeft)
	ld hl, FE_TurnChoiceLeft
	call FarCall_A_HL
.skip_7d23:
	ldh a, [hFE_JoyInput]
	and $09
	jr z, .skip_7d32
	ld b, a
	ldh a, [hFE_JoyPrevious]
	and $09
	and b
	call z, FE_LanguageSelect_Done
.skip_7d32:
	call FE_LanguageSelect_Draw
	jr FE_LanguageSelect_Input


FE_LanguageSelect_Done::
	call FE_FadeOutScreenSlow
	di
	xor a
	ldh [rIE], a
	ldh [rIF], a
	ld a, BANK(FE_RestoreHRAM)
	ld hl, FE_RestoreHRAM
	call FarCall_A_HL
	ld a, [wFE_GameSP]
	ld l, a
	ld a, [wFE_GameSP + 1]
	ld h, a
	ld sp, hl
	ld a, [wFE_Choice]
	ld l, a
	ld d, $01
	ret


FE_LanguageSelect_Draw::
	ld a, $01
	ldh [rSVBK], a
	ld a, BANK(FE_ClearOAM)
	ld hl, FE_ClearOAM
	call FarCall_A_HL
	ld e, $00
	xor a
	ldh [hFE_Scratch2], a
	ld a, BANK(FE_DrawRingItems)
	ld hl, FE_DrawRingItems
	call FarCall_A_HL
	ld a, [wFE_Choice]
	ldh [hFE_Scratch], a
	ld bc, $3818
	ld a, $06
	ldh [hFE_Scratch2 + 1], a
	ld d, $0a
	ld a, BANK(FE_DrawSpriteAnim)
	ld hl, FE_DrawSpriteAnim
	call FarCall_A_HL
	xor a
	ldh [rVBK], a
	ld hl, wFE_ScreenBuffer
	ld bc, $8000
	ldh a, [hFE_Scratch2]
	dec a
	ld d, a
	xor a
	ldh [hFE_VBlankFlag], a
.loop:
	ldh a, [hFE_VBlankFlag]
	cp $01
	jr nz, .loop
	call FE_HDMA
	call FE_OAMDMA
	ldh a, [rSCX]
	add a, $fc
	ldh [rSCX], a
	ldh a, [rSCY]
	add a, $fc
	ldh [rSCY], a
	ret

	ds 592, $00 ; $7db0

